<?php

declare(strict_types=1);

use Illuminate\Foundation\Testing\RefreshDatabase;
use Tests\TestCase;

uses(TestCase::class)->in('Feature', 'Unit');

// The whole directory, deliberately. Enumerating files here meant a new test
// file quietly shared state with the previous one and its assertions counted
// rows it never created, which is a worse failure than a missing database
// because it looks like a bug in the code under test.
uses(RefreshDatabase::class)->in('Feature');

/**
 * Synthetic frames, generated by this project's encoder. Never captured.
 *
 * @return array<string, string>
 */
function frames(): array
{
    /** @var array<string, string> $fixtures */
    $fixtures = require __DIR__.'/Fixtures/frames.php';

    return $fixtures;
}

/** @param list<string> $names */
function postFrames(array $names, array $extra = []): Illuminate\Testing\TestResponse
{
    $available = frames();

    return test()->withToken(config('aera.ingest_token'))->postJson('/api/ingest', [
        'frames' => array_map(fn (string $name): string => $available[$name], $names),
        ...$extra,
    ]);
}
